import type { CSSProperties } from "react";

import type { AudioVisualizerProps } from "@/components/control-ui/contracts";
import { cn } from "@/components/control-ui/lib/cn";

// Bars reading. audio-visualizer-line.tsx exports same `AudioVisualizer` on same props, so swapping is import-path change.
// Runtime-agnostic — feed it any rolling 0..1 window.

type AudioVisualizerLevelStyle = CSSProperties & Record<"--_audio-visualizer-level-opacity", string>;

const DEFAULT_POINTS = 28;
const MAX_POINTS = 128;
const MIN_VISIBLE_LEVEL = 0.12;

// local so either visualizer installs as complete, independent choice
function resolveAudioVisualizerLevels(levels: readonly number[], points?: number) {
  const requestedPoints = Number.isFinite(points) ? Math.floor(points ?? DEFAULT_POINTS) : DEFAULT_POINTS;
  const pointCount = Math.min(MAX_POINTS, Math.max(1, requestedPoints));
  const visible = levels.slice(-pointCount).map((level) => (Number.isFinite(level) ? Math.min(1, Math.max(0, level)) : 0));
  const padded = visible.length === pointCount ? visible : [...new Array<number>(pointCount - visible.length).fill(0), ...visible];
  return padded.map((level, position) => ({ key: `bar-${position}`, level }));
}

export function AudioVisualizer({ levels, points, active = true, className, style, ...props }: AudioVisualizerProps) {
  const visible = resolveAudioVisualizerLevels(levels, points);

  return (
    <div
      data-control-ui="audio-visualizer"
      data-control-family="audio-visualizer"
      data-slot="root"
      data-variant="bars"
      data-active={active ? "true" : undefined}
      aria-hidden="true"
      className={cn("h-7 w-44 shrink-0 overflow-hidden px-1.5 py-1.5", className)}
      style={style}
      {...props}
    >
      <span
        data-control-ui="audio-visualizer"
        data-control-family="audio-visualizer"
        data-slot="track"
        data-active={active ? "true" : undefined}
        className="flex size-full items-stretch justify-end gap-px mask-l-from-90%"
      >
        {visible.map(({ key, level }) => {
          const perceptualLevel = Math.sqrt(level);
          const visibleLevel = MIN_VISIBLE_LEVEL + perceptualLevel * (1 - MIN_VISIBLE_LEVEL);
          const levelStyle: AudioVisualizerLevelStyle = {
            "--_audio-visualizer-level-opacity": `${0.48 + perceptualLevel * 0.52}`,
            clipPath: `inset(${(1 - visibleLevel) * 50}% 0 round var(--radius-control))`,
          };

          return (
            <span
              key={key}
              data-control-ui="audio-visualizer"
              data-control-family="audio-visualizer"
              data-slot="bar-track"
              className="flex w-1 shrink-0 items-center"
            >
              <span
                data-control-ui="audio-visualizer"
                data-control-family="audio-visualizer"
                data-slot="bar"
                className="block h-full w-full"
                style={levelStyle}
              />
            </span>
          );
        })}
      </span>
    </div>
  );
}

@layer components {
  :where([data-control-family="audio-visualizer"][data-slot="root"]) {
    --audio-visualizer-radius: var(--radius-control);
    --audio-visualizer-bar-background: oklch(from var(--primary) l c h / 0.8);
    --audio-visualizer-line-fill: oklch(from var(--primary) l c h / 0.18);
    --audio-visualizer-line-stroke: oklch(from var(--primary) l c h / 0.8);
  }
  :where([data-control-family="audio-visualizer"][data-slot="root"][data-variant]) {
    --_audio-visualizer-bar-track-filter: none;
    border-radius: var(--audio-visualizer-radius);
  }

  :where([data-control-family="audio-visualizer"][data-slot="track"]) {
    opacity: 0.55;
    transition: opacity var(--duration-base) var(--ease-standard);
  }

  :where([data-control-family="audio-visualizer"][data-slot="track"][data-active="true"]) {
    opacity: 1;
  }

  :where([data-control-family="audio-visualizer"][data-slot="bar-track"]) {
    transition: opacity var(--duration-base) var(--ease-emphasized), filter var(--duration-base) var(--ease-emphasized), translate var(--duration-base) var(--ease-emphasized);
  }

  @starting-style {
    :where([data-control-family="audio-visualizer"][data-slot="bar-track"]) {
      opacity: 0;
    }
  }

  :where([data-control-family="audio-visualizer"][data-slot="bar"]) {
    background: var(--audio-visualizer-bar-background);
    border-radius: var(--radius-control);
    opacity: var(--_audio-visualizer-level-opacity);
    transition: clip-path var(--duration-base) var(--ease-standard), opacity var(--duration-base) var(--ease-standard);
  }

  :where([data-control-family="audio-visualizer"][data-slot="baseline"]) {
    stroke: oklch(from var(--border) l c h / 0.55);
  }

  :where([data-control-family="audio-visualizer"][data-slot="waveform"]) {
    fill: var(--audio-visualizer-line-fill);
    stroke: var(--audio-visualizer-line-stroke);
    transition: d var(--duration-base) var(--ease-standard);
  }

  :where([data-control-family="audio-visualizer"][data-slot="bar-track"]) {
    filter: var(--_audio-visualizer-bar-track-filter);
  }

  @starting-style {
    :where([data-control-family="audio-visualizer"][data-slot="bar-track"]) {
      --_audio-visualizer-bar-track-filter: blur(var(--blur-xs));
      filter: var(--_audio-visualizer-bar-track-filter);
    }
  }

  @starting-style {
    :where([data-control-family="audio-visualizer"][data-slot="bar-track"]) {
      --_audio-visualizer-bar-track-translate: var(--spacing) 0;
      translate: var(--_audio-visualizer-bar-track-translate);
    }
  }
}

@property --audio-visualizer-radius {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --audio-visualizer-bar-background {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --audio-visualizer-line-fill {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --audio-visualizer-line-stroke {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}
